INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1292508-coe399', 'stk-sultan11', 'COE 399', 'info', '{"desc": "أظنّ الكورس هذا ما يتقيّم .\n\nبس لعيون الجميع … و بما إني فاضي بأقيّمة .\n\nأول شي لازم تكون مخلص شغلتين عشان تكون مرشح للتدريب . الأولى ENGL 214 و الثانية تكون Junior . كثير يقولون غير هالكلام بس خلك منهم .\n\nالشي الثاني … لازم تعرف إن فيه 4 كورسات إختيارية من التخصص لازم تاخذها لو طبقت صيفي بعكس طلاب التطبيق التعاوني ياخذون كورسين أو كورس أو لا شي > ماني متأكد .\n\nالشي الثالث وهو الاهم … لازم تعرف أن الحصول على تدريب صيفي هو أمر صعب لكل التخصصات … و صعب أكثر لتخصصنا .\n\nعموماً الحمد لله أخذت التدريب الصيفي في ترم 123 و كنت مع شركة في الرياض . الأهم إن الشركة غالباً بتكون ما هي عارفة وش تسوي بك … فأنصحك بالإطّلاع على مشاريعهم و أختيار شي ممكن تساهم فيه أو تعيد تصميمه … أفضل ما يحطونك في الداتا إنتري ولا شي مكتبي تجلس تتفرج فيهم .\n\nشخصياً أشتغلت على بروجكت له علاقة بالهاردوير بعد نشبة للشركة . أستفدت من البروجكت و أفدت الشركة .\n\nالدروس اللي تعلمتها من التدريب هي الإنظباطية في الحضور لأنها تكلفك فلوس من راتبك . أيضاً أن الوقت مهم … لازم تقدم شي لأنك تخسّر الشركة لو ما قدمت الشي ( كموظف ) .\n\nاكتشفت أن سوق العمل مو عارف وش طلاب هندسة الحاسب بالظبط !! كثير أعرفهم أشتغلوا شغل الـ ICS و الـ SWE . طبعاً ما أعرف إلا صديق واحد أشتغل في مجال النيتووركنق في التدريب الحالي لكنه كوأب .\n\nأهم نصيحة ممكن أقدمها إنك تظبط نفسك بدري لأن التدريب الصيفي لو أظطريت تأجله بتروح عليك سنة كاملة .\n\nأمنياتي للمهندسين الـ Geeks بالتوفيق 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coe-399-summer-training/120823/2", "user": "Sultan11", "ts": 1385172970000, "tid": 120823, "pn": 2}}', 1385172970000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
